package cu.hogarplaya;
import org.json.*;
public class SharedCartLiveTest {
 static int n;static void ok(boolean b){if(!b)throw new AssertionError();n++;}
 static JSONObject empty()throws Exception{return new JSONObject("{products:[],offers:[],shared:[],queue:[],conflicts:[]}");}
 static JSONArray cart()throws Exception{return new JSONArray("[{id:'l1',productId:'p1',name:'Papa',quantity:2,unitCode:'lb'}]");}
 static JSONObject share()throws Exception {return SharedCartLive.noteShare(SharedCartPlan.plan(empty(),cart(),"p","d","h"),cart(),"p","d","h");}
 static JSONObject ack(JSONObject v)throws Exception {
  v=new JSONObject(v.toString());JSONArray batch=v.getJSONArray("queue"),rows=v.getJSONArray("shared");JSONObject op=batch.getJSONObject(0);JSONObject r=new JSONObject(op.getJSONObject("item").toString()).put("revision",op.getInt("baseRevision")+1).put("lastChangeId",op.getString("id"));JSONArray next=new JSONArray();for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getString("id").equals(r.getString("id")))next.put(rows.getJSONObject(i));next.put(r);v.put("shared",next).put("queue",new JSONArray());return SharedCartLive.acknowledged(v,batch,new JSONArray());
 }
 public static void main(String[] args)throws Exception {
  JSONObject v=share(),q=v.getJSONArray("queue").getJSONObject(0),item=new JSONObject(q.getJSONObject("item").toString());String immutable=q.toString();item.put("bought",true);JSONObject changed=SharedCartLive.change(v,item,"p",0);ok(changed.getJSONArray("queue").getJSONObject(0).toString().equals(immutable));ok(changed.getJSONObject("sharedIntents").getJSONObject(item.getString("id")).getJSONObject("item").getBoolean("bought"));ok(v.optJSONObject("sharedIntents")==null);
  JSONObject sent=ack(changed);ok(sent.getJSONArray("queue").length()==1);JSONObject follow=sent.getJSONArray("queue").getJSONObject(0);ok(!q.getString("id").equals(follow.getString("id")));ok(follow.getInt("baseRevision")==1);ok(follow.getJSONObject("item").getBoolean("bought"));sent=ack(sent);ok(sent.getJSONArray("queue").length()==0);ok(sent.getJSONObject("sharedIntents").length()==0);
  JSONObject removal=new JSONObject(item.toString()).put("deleted",true);JSONObject pending=SharedCartLive.change(sent,removal,"p",2);JSONObject undo=SharedCartLive.change(pending,new JSONObject(removal.toString()).put("deleted",false),"p",2);ok(undo.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("deleted"));JSONObject undone=ack(ack(undo));ok(!undone.getJSONArray("shared").getJSONObject(0).getBoolean("deleted"));
  JSONObject delayed=share();String sentId=delayed.getJSONArray("queue").getJSONObject(0).getString("id");delayed=ack(delayed);JSONObject later=SharedCartLive.change(delayed,item,"p",0,sentId);ok(later.getJSONArray("conflicts").length()==0);ok(later.getJSONArray("queue").getJSONObject(0).getInt("baseRevision")==1);
  JSONObject remote=ack(share());JSONObject remoteItem=remote.getJSONArray("shared").getJSONObject(0);remoteItem.put("quantity",9).put("revision",2).put("lastChangeId","other-device");JSONObject conflict=SharedCartLive.change(remote,new JSONObject(item.toString()).put("quantity",3),"p",1);ok(conflict.getJSONArray("queue").length()==0);ok(conflict.getJSONArray("conflicts").length()==1);String id=conflict.getJSONArray("conflicts").getJSONObject(0).getJSONObject("local").getString("id");JSONObject mine=SharedCartLive.resolve(conflict,id,true,"p");ok(mine.getJSONArray("queue").getJSONObject(0).getInt("baseRevision")==2);ok(mine.getJSONArray("conflicts").length()==0);ok(SharedCartLive.resolve(conflict,id,false,"p").getJSONObject("sharedIntents").length()==0);
  JSONObject original=ack(share());String before=original.toString();JSONArray edited=cart();edited.getJSONObject(0).put("quantity",4);JSONObject edit=SharedCartLive.changedCart(original,edited,new JSONObject(),"p","cart","d","h");ok(edit.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getDouble("quantity")==4);ok(original.toString().equals(before));
  JSONObject deleted=SharedCartLive.changedCart(original,new JSONArray(),new JSONObject(),"p","cart","d","h");ok(deleted.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("deleted"));ok(!deleted.getJSONObject("sharedCartActive").optBoolean("p"));
  JSONObject bought=SharedCartLive.changedCart(original,new JSONArray(),new JSONObject(),"p","purchased","d","h");ok(bought.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("bought"));ok(!bought.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("deleted"));
  JSONArray added=cart();added.put(new JSONObject("{id:'l2',name:'Zanahoria',quantity:1,unitCode:'kg'}"));ok(SharedCartLive.changedCart(original,added,new JSONObject(),"p","cart","d","h").getJSONArray("queue").length()==1);
  JSONObject shopLine=new JSONObject(cart().getJSONObject(0).toString()).put("id","shopping-id");JSONObject shop=new JSONObject().put("active",true).put("lines",new JSONArray().put(shopLine));JSONObject transfer=SharedCartLive.changedCart(original,new JSONArray(),shop,"p","transfer","d","h");ok(transfer.getJSONArray("queue").length()==0);shopLine.put("bought",true);JSONObject modeBuy=SharedCartLive.changedCart(transfer,new JSONArray(),shop,"p","shopping","d","h");ok(modeBuy.getJSONArray("queue").getJSONObject(0).getJSONObject("item").getBoolean("bought"));
  JSONObject legacy=SharedCartPlan.plan(empty(),cart(),"p","d","h");ok(SharedCartLive.migrate(legacy,cart(),"p","d","h").has("sharedCartOwners"));ok(SharedCartLive.changedCart(original,new JSONArray(),new JSONObject(),"another-person","purchased","d","h").getJSONArray("queue").length()==0);
  JSONObject full=ack(share());for(int i=0;i<100;i++)full.getJSONArray("queue").put(new JSONObject().put("id","q"+i).put("entityId","e"+i));JSONObject buffered=SharedCartLive.change(full,item,"p",1);ok(buffered.getJSONArray("queue").length()==100);ok(buffered.getJSONObject("sharedIntents").length()==1);
  System.out.println("PASS: "+n+" live checks; recibos inmutables, cola de intenciones, borrado/deshacer, conflictos, edición, compra real, importación y conservación financiera.");
 }
}
